8.5 FinancialEngine 
C# - FinancialEngine 
public static class FinancialEngine { 
    public static RoundResult Calculate(PlayerState state, int round, float 
eventImpact) {


Público 
        float coherenceFactor = 
CoherenceSystem.GetFactor(state.CoherenceRating); 
        float reputationMod   = Mathf.Lerp(0.5f, 1.5f, state.ReputationScore / 
100f); 

        float revenue   = state.Config.BaseMonthlyRevenue 
                        * coherenceFactor * reputationMod; 
        float supplies  = revenue * 0.30f; 
        float rent      = state.Config.Location.Rent; 
        float salaries  = state.Config.TotalMonthlySalary; 
        float utilities = state.Config.Restaurant.BaseMonthlyCost; 
        float loan      = LoanCalculator.GetMonthlyPayment(state); 
        float thirteenth = (round == 12) ? salaries : 0f; 

        float totalCosts = supplies + rent + salaries + utilities + loan 
                         + thirteenth + eventImpact; 
        float netResult  = revenue - totalCosts; 

        return new RoundResult { 
            GrossRevenue = revenue, SupplyCost = supplies, 
            Rent = rent, Salaries = salaries, Utilities = utilities, 
            LoanPayment = loan, ThirteenthSalary = thirteenth, 
            EventCashImpact = eventImpact, NetResult = netResult, 
            OpeningCash = state.CurrentCash, 
            ClosingCash = state.CurrentCash + netResult 
        }; 
    } 
}


